Legacy Script
Treated as an opaque black box, exactly as in the vignette – we recover its mapping logic by extraction rather than by reading it:


Code
# -- The "opaque legacy script" this site extracts crossmaps from --
#
# Ported verbatim from conformr-indstat/code/fncs_cleaning.R. Treated as a
# black box for the purposes of this demo: extract_naive_weights() (R/extract.R)
# recovers the isiccomb -&gt; isic mapping this function implies by running it
# on masked ("carbon paper") data, rather than trusting/reading its logic
# directly -- see CLAUDE.md, "Naive-weight extraction".

subset_34_from_total &lt;- function(combined_df, total_letter) {
  subsets &lt;- list()

  subsets$threefour &lt;-
    combined_df |&gt;
    dplyr::filter(isic != total_letter)

  subsets$totalrows &lt;-
    combined_df |&gt;
    dplyr::filter(isic == total_letter) |&gt;
    tidyr::pivot_wider(id_cols = c(country, year), names_from = isic, values_from = value) |&gt;
    dplyr::rename(total.row = dplyr::all_of(total_letter))

  testthat::test_that("All rows from combined_df are accounted for in subsets", {
    nrow.combined_df &lt;- nrow(combined_df)
    nrow.subsets &lt;- sum(sapply(subsets, nrow))
    testthat::expect_true(nrow.combined_df == nrow.subsets)
  })

  return(subsets)
}

split_isiccomb &lt;- function(threefour_df) {
  interim &lt;- list()

  interim$isiccomb.rows &lt;-
    threefour_df |&gt;
    dplyr::filter(stringr::str_detect(isiccomb, "[:alpha:]"))

  testthat::test_that("No `country,year` has more than one recorded `value` per `isiccomb` group", {
    rows_w_many_values_per_isiccomb &lt;-
      interim$isiccomb.rows |&gt;
      dplyr::group_by(country, year, isiccomb) |&gt;
      dplyr::summarise(n_obs = sum(!is.na(value)), .groups = "drop") |&gt;
      dplyr::filter(n_obs != 1) |&gt;
      nrow()
    testthat::expect_true(rows_w_many_values_per_isiccomb == 0)
  })

  interim$isiccomb.avg &lt;-
    interim$isiccomb.rows |&gt;
    dplyr::group_by(country, year, isiccomb) |&gt;
    dplyr::mutate(value = tidyr::replace_na(value, 0)) |&gt;
    dplyr::summarise(
      avg.value = mean(value),
      n_isic = dplyr::n_distinct(isic),
      n_rows = dplyr::n(),
      .groups = "drop_last"
    ) |&gt;
    dplyr::mutate(row_check = (n_isic == n_rows))

  testthat::test_that("isiccomb split average is calculated with correct denominator", {
    testthat::expect_true(all(interim$isiccomb.avg$row_check))
  })

  final &lt;-
    dplyr::left_join(threefour_df, interim$isiccomb.avg, by = c("country", "year", "isiccomb")) |&gt;
    dplyr::rename(value.nosplit = value) |&gt;
    dplyr::mutate(
      value = dplyr::coalesce(avg.value, value.nosplit),
      split.isiccomb = !is.na(avg.value)
    ) |&gt;
    dplyr::select(country, year, isic, isiccomb, value, value.nosplit, split.isiccomb)

  return(final)
}

Naive-Weight Extraction
Masking must preserve NAs – an unconditional mask would turn originally-missing cells into “recorded” ones, breaking split_isiccomb()’s own internal invariant check (exactly one recorded value per isiccomb group). See the comment in R/extract.R; this was a real bug caught while building this page, not a theoretical concern.


Code
# -- Naive-weight extraction (the "carbon paper" technique) --
# See CLAUDE.md, "Naive-weight extraction", and xmap's
# extracting-crossmaps-from-scripts.Rmd vignette (PR #4, Case 2).

extract_naive_weights &lt;- function(threefour_df, mask_value = 1000) {
  threefour_df |&gt;
    ## mask *recorded* values only -- an unconditional overwrite would turn
    ## NA cells into "recorded", breaking split_isiccomb()'s own internal
    ## invariant check ("exactly one recorded value per isiccomb group")
    dplyr::mutate(value = ifelse(is.na(value), NA, mask_value)) |&gt;
    split_isiccomb() |&gt;
    dplyr::mutate(weight = value / mask_value) |&gt;
    tidyr::drop_na(weight)
}

# Validate every (country, year) group's links as its own crossmap --
# a crossmap collection is many small crossmaps stacked in one table, so
# validity is a per-group property (diagnose_as_xmap_tbl() checks one
# crossmap at a time), not something that can be checked across the whole
# table at once.
diagnose_grouped_xmap &lt;- function(links, .from, .to, .weight_by) {
  links |&gt;
    dplyr::group_by(country, year) |&gt;
    dplyr::group_map(\(group_df, group_key) {
      diagnosis &lt;- xmap::diagnose_as_xmap_tbl(group_df, {{ .from }}, {{ .to }}, {{ .weight_by }})
      dplyr::bind_cols(
        group_key,
        tibble::tibble(data = list(group_df), valid = diagnosis$valid, diagnosis = list(diagnosis))
      )
    }) |&gt;
    dplyr::bind_rows()
}

# Compose one xmap1 per (country, year) group against a single shared xmap2
# (xmap::compose_xmap() only takes one xmap1/xmap2 pair at a time -- grouped
# composition is left to the caller, per xmap#29's resolution). Mirrors
# diagnose_grouped_xmap()'s per-group dplyr::group_map() pattern above.
compose_grouped_xmap &lt;- function(links1, xmap2, .from, .via, .weight_by) {
  links1 |&gt;
    dplyr::group_by(country, year) |&gt;
    dplyr::group_map(\(group_df, group_key) {
      xmap1 &lt;- xmap::as_xmap_tbl(group_df, {{ .from }}, {{ .via }}, weight_by = {{ .weight_by }})
      composed &lt;- xmap::compose_xmap(xmap1, xmap2) |&gt; tidyr::unpack(dplyr::everything())
      dplyr::bind_cols(group_key, composed)
    }) |&gt;
    dplyr::bind_rows() |&gt;
    dplyr::rename(weight = weight_by)
}




