  ([, rows]) =&gt; -rows.length
)

nodeLinkOverview = html`&lt;div style="display:flex; flex-wrap:wrap; gap:1rem; align-items:flex-start;"&gt;
  ${codeGroups.map(([isiccombCode, rows]) =&gt; {
    const cov = coverage.get(isiccombCode);
    const countLabel = `${cov.n_country} countr${cov.n_country === 1 ? "y" : "ies"}, ${cov.n_ctryr} country-yr${cov.n_ctryr === 1 ? "" : "s"}`;
    return html`&lt;div style="border:1px solid #ddd; border-radius:6px; padding:0.5rem;" title="${countLabel}\n${cov.coverage_detail}"&gt;
      &lt;div style="font: 600 12px sans-serif; margin-bottom:2px;"&gt;${isiccombCode} (${rows.length} isic.3 parents)&lt;/div&gt;
      &lt;div style="font: 10px sans-serif; color:#666; margin-bottom:4px;"&gt;${cov.coverage_summary}&lt;/div&gt;
      ${buildComposedNodeLink2Col(d3, rows)}
    &lt;/div&gt;`;
  })}
&lt;/div&gt;`

nodeLinkOverview
